import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"合入门槛（PR 规范）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/pr-workflow.md","filePath":"zh/dev/pr-workflow.md"}'),l={name:"zh/dev/pr-workflow.md"};function d(c,o,i,s,n,p){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="合入门槛-pr-规范" tabindex="-1">合入门槛（PR 规范） <a class="header-anchor" href="#合入门槛-pr-规范" aria-label="Permalink to &quot;合入门槛（PR 规范）&quot;">​</a></h1><p>PR 必须按顺序通过以下审核：</p><ol><li><strong>干净构建</strong>：在本地机器和 CI 上均通过 <code>make kernel</code> 且带上 <code>-Wall -Wextra -Werror</code> 参数（CI 的工具链通常更严格；multiboot2 打包转换与 rdrand setc 修复的存在，正是因为运行器上的更严格的 GCC/GAS 发现了本地构建所接受的问题）。</li><li><strong>宿主测试</strong>：<code>make test</code> - 零失败。</li><li><strong>启动测试</strong>：<code>make run-bios</code> 和 <code>make run-uefi</code> - 两者都应到达 <code>oc&gt;</code> 提示符并显示 <code>boot complete ... OK</code>。</li><li><strong>针对你所修改内容的深度测试</strong> - <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a> 中的矩阵（存储 -&gt; fstest；加密 -&gt; cryptotest + HTTPS E2E；看门狗/klog/健康监控 -&gt; WP-12 E2E；启动路径 -&gt; 28 项回归检查）。</li><li><strong>可复现性检查</strong>：<code>make reproducible-check</code> 输出 PASS。</li><li><strong>文档同步</strong>：新增命令 -&gt; 生成其参考页（<code>make api-docs</code> 会刷新 <code>docs/manual/commands/</code> 和 <code>INTERFACES.md</code>）；新增接口 -&gt; 更新接口面表格；行为变更 -&gt; 更新对应的用户手册页面。</li><li><strong>CI 通过</strong>：工作流在每次 PR 上都会运行构建、ISO 打包、宿主测试和可复现性门禁 - 仅在全部通过时才允许合并。</li></ol><h2 id="pr-描述撰写" tabindex="-1">PR 描述撰写 <a class="header-anchor" href="#pr-描述撰写" aria-label="Permalink to &quot;PR 描述撰写&quot;">​</a></h2><ul><li>变更内容与原因 - 提交信息已包含详细说明。</li><li>你运行了哪些测试（命令 + 结果行，直接粘贴）。</li><li>你刻意未完成的事项（范围边界）。</li></ul><h2 id="审核预期" tabindex="-1">审核预期 <a class="header-anchor" href="#审核预期" aria-label="Permalink to &quot;审核预期&quot;">​</a></h2><p>请准备好回答关于错误路径、DMA 边界以及硬件撒谎时会发生什么（截断的表、卡住的 NAK、返回垃圾数据的设备）的问题。项目自身的历史记录 - BUG-0136..0238 - 正是这些问题的目录；阅读其中几个修复提交是最好的准备方式。</p>',7)])])}const h=e(l,[["render",d]]);export{g as __pageData,h as default};
